package ozl.environment;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Session contract probes; no game process is initialized. */
public final class ServerManifestTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}static Path put(Path path,String text)throws Exception{Files.createDirectories(path.getParent());Files.write(path,text.getBytes(StandardCharsets.UTF_8));return path;}static String row(String key,String... values){StringBuilder s=new StringBuilder(key);for(String value:values)s.append('\t').append(Base64.getEncoder().encodeToString(value.getBytes(StandardCharsets.UTF_8)));return s.append('\n').toString();}
 public static void main(String[] args)throws Exception{Path base=Paths.get(args[0]).toAbsolutePath(),game=Files.createDirectories(base.resolve("game")),user=Files.createDirectories(base.resolve("user")),context=Files.createDirectories(base.resolve("context")),session=Files.createDirectories(context.resolve("live"));put(session.resolve("mods/default.txt"),"session");put(session.resolve("mods/loaded.txt"),"session");Path local=base.resolve("local/ClientExtension"),server=base.resolve("server/ClientExtension"),extra=base.resolve("local/ExtraClient"),ordinary=base.resolve("workshop/PlainLua"),bridge=session.resolve("bridge");put(local.resolve("42/mod.info"),"id=ClientExtension\n");put(server.resolve("42/mod.info"),"id=ClientExtension\n");put(extra.resolve("42/mod.info"),"id=ExtraClient\n");put(ordinary.resolve("42/mod.info"),"id=PlainLua\n");put(bridge.resolve("42/mod.info"),"id=OrangeLauncherSession\n");
 String common="OZLLIVE1\n"+row("game",game.toString())+row("user",user.toString())+row("context",context.toString())+row("choices",session.toString())+row("vanilla","false");String pins=row("managed","ClientExtension")+row("selected","ClientExtension",local.toString())+row("component","ClientExtension")+row("order","ClientExtension")+row("managed","ExtraClient")+row("selected","ExtraClient",extra.toString())+row("component","ExtraClient")+row("order","ExtraClient")+row("managed","OrangeLauncherSession")+row("selected","OrangeLauncherSession",bridge.toString())+row("component","OrangeLauncherSession");Path file=put(session.resolve("live.manifest"),common+pins+row("server-components","follow-server"));LiveEnvironmentManifest follow=LiveEnvironmentManifest.read(file,LiveEnvironmentManifest.sha(file),game);List<String> ids=new ArrayList<String>(Arrays.asList("ServerSecond","\\ClientExtension","ServerFirst"));follow.mergeClient(ids);check(ids.equals(Arrays.asList("ServerSecond","\\ClientExtension","ServerFirst")),"follow-server preserves exact server list without component/bridge injection");List<String> roots=new ArrayList<String>(Arrays.asList(server.toString(),ordinary.toString()));follow.filter(roots,true,new HashSet<String>(Arrays.asList("ClientExtension")));check(roots.equals(Arrays.asList(server.toString(),ordinary.toString())),"follow-server preserves native discovery without local pin replacement");List<String> menu=new ArrayList<String>(Arrays.asList("ClientExtension","PlainLua"));follow.normalize(menu);check(menu.equals(Arrays.asList("OrangeLauncherSession")),"local Java is deferred until the actual server selection to preserve same-ID server priority");check(follow.usesBuddyApproval(),"server delegates Java decisions to native Buddy");Path late=put(base.resolve("server/Late/42/new.jar"),"created after manifest acceptance");check(!follow.allows(late,"fixture.late"),"delegation does not manufacture a static approval for late Java");
 put(file,common+pins+row("server-components","force-local"));LiveEnvironmentManifest force=LiveEnvironmentManifest.read(file,LiveEnvironmentManifest.sha(file),game);ids=new ArrayList<String>(Arrays.asList("ServerSecond","\\ClientExtension","ServerFirst"));force.mergeClient(ids);check(ids.equals(Arrays.asList("ServerSecond","\\ClientExtension","ServerFirst","ExtraClient")),"force-local appends every missing client component in validated order and deduplicates qualified server IDs");force.mergeClient(ids);check(ids.size()==4,"force-local merge remains idempotent");roots=new ArrayList<String>(Arrays.asList(server.toString(),ordinary.toString(),local.toString()));force.filter(roots,true,new HashSet<String>(Arrays.asList("ClientExtension")));check(roots.indexOf(server.toString())>=0&&!roots.contains(local.toString())&&roots.contains(extra.toString()),"same-ID server source wins while absent forced component uses selected local source");
 roots=new ArrayList<String>(Arrays.asList(server.toString(),ordinary.toString()));force.filter(roots,false,Collections.<String>emptySet());check(roots.equals(Arrays.asList(bridge.toString())),"initial menu only exposes bridge/loader and cannot cache a local same-ID client source");put(file,common+pins);LiveEnvironmentManifest single=LiveEnvironmentManifest.read(file,LiveEnvironmentManifest.sha(file),game);check(!single.usesBuddyApproval()&&!single.allows(late,"fixture.late"),"ordinary single-player still rejects unselected Java");System.out.println("PASS "+checks+" server manifest assertions; no game launched");}
}
